list_shipping_rates.code:
import com.webcommander.client.ApiResponse;
import java.util.List;
import java.util.Map;

ApiResponse response = client.shippingRates().listShippingRates(Map.of("method", "flat_rate", "handling_cost", "with_handling", "sort", "name", "order", "asc"));
Map<?, ?> body = (Map<?, ?>) response.getMap();
for (Object row : (List<?>) body.get("shipping_rates")) {
    Map<?, ?> rate = (Map<?, ?>) row;
    System.out.println(rate.get("id") + " " + rate.get("name") + " " + rate.get("method"));
}
System.out.println(((Map<?, ?>) body.get("pagination")).get("has_next"));

