create_shipping_rate.code:
import com.webcommander.client.ApiResponse;
import java.util.Map;

ApiResponse response = client.shippingRates().createShippingRate(Map.of("shipping_rate", Map.of(
        "name", "Flat 10", "method", "flat_rate",
        "shipping_cost", Map.of("amount", 10, "type", "fixed"),
        "handling_cost", Map.of("amount", 5, "type", "percent"))));
Map<?, ?> shippingRate = (Map<?, ?>) ((Map<?, ?>) response.getMap()).get("shipping_rate");
System.out.println(shippingRate.get("id") + " " + shippingRate.get("name") + " " + shippingRate.get("method"));
System.out.println(shippingRate.get("shipping_cost") + " " + shippingRate.get("handling_cost"));

